    let s1 = "12"
    let s2 = "x"
    let s3 = "30"
    let sum = match parse(s1) {
        Some(n) => n,
        _ => 0,
    }
    let count = match parse(s2) {
        Some(_) => 1,
        _ => 0,
    }
    print(sum + count)
}

